std::set<int> s = {10, 20, 30, 40};

auto it = s.find(30); // Iterator initialized

// Core Bidirectional Traversal
// 1. Forward movement (O(1) amortized)
it++; // it now points to 40 (successor)

// 2. Backward movement (O(1) amortized)
it--; // it now points back to 30

// Reverse Iterator (uses bidirectionality internally)
auto rit = s.rbegin(); // rit == 40
rit++;                // rit == 30
auto rend_it = s.rend(); // one step before begin()
